import { Group, Mesh, PlaneGeometry } from '@/primitives';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group: THREEGroup } = ctx.THREE;
  const root = new THREEGroup();

  // ----- Sizes -----
  const WIDTH = 6.8;
  const HEIGHT = 2.0;
  const HALF_W = WIDTH / 2;
  const HALF_H = HEIGHT / 2;

  // ----- Gradient Backdrop -----
  const backdropGeo = new PlaneGeometry(WIDTH, HEIGHT);
  const backdropMat = new MeshStandardNodeMaterial();
  backdropMat.colorNode = mix(color('#121218'), color('#0b0b10'), uv().y);
  backdropMat.roughness = 0.6;
  backdropMat.metalness = 0.2;
  backdropMat.transparent = true;
  backdropMat.opacity = 0;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  root.add(backdrop);

  // ----- Top Hairline -----
  const lineGeo = new PlaneGeometry(WIDTH, 0.006);
  const lineMat = new MeshStandardNodeMaterial({ color: '#23232b', roughness: 0.9, metalness: 0.0 });
  lineMat.transparent = true;
  lineMat.opacity = 0;
  const topLine = new Mesh(lineGeo, lineMat);
  topLine.position.set(0, HALF_H - 0.003, 0.001);
  root.add(topLine);

  // ----- Bottom Hairline (above legal) -----
  const bottomLine = new Mesh(lineGeo.clone(), lineMat.clone());
  const bottomLineY = -HALF_H + 0.25 + 0.003;
  bottomLine.position.set(0, bottomLineY, 0.001);
  root.add(bottomLine);

  // ----- Accent Bar -----
  const accentBarGeo = new PlaneGeometry(0.3, 0.02);
  const accentBarMat = new MeshStandardNodeMaterial({ color: '#ff2a38', emissive: '#ff2a38', emissiveIntensity: 1.4, roughness: 0.6, metalness: 0.2 });
  accentBarMat.transparent = true;
  accentBarMat.opacity = 0;
  const accentBar = new Mesh(accentBarGeo, accentBarMat);
  accentBar.position.set(-HALF_W + 1.0, 0.35, 0.001);
  root.add(accentBar);

  // ----- Helper to collect meshes for fade‑up -----
  const fadeMeshes = [];
  root.traverse((obj) => {
    if (obj.isMesh) {
      obj.material.transparent = true;
      obj.material.opacity = 0;
      fadeMeshes.push(obj);
    }
  });

  // ----- Text creation helper -----
  const createText = (content, opts, pos) => {
    const txt = ctx.fontAtlas.createText(content, opts);
    txt.position.set(pos.x, pos.y, pos.z ?? 0);
    root.add(txt);
    return txt;
  };

  // ----- Wordmark -----
  const wordmarkOpts = {
    fontSize: 34,
    color: '#16161d',
    align: 'left',
  };
  const wordmark = createText('NOVA ATELIER', wordmarkOpts, { x: -HALF_W + 1.0, y: 0.55 });

  // ----- Column data -----
  const columns = [
    {
      header: 'ATELIER',
      links: ['Features', 'Collection', 'Pricing'],
    },
    {
      header: 'COMPANY',
      links: ['Journal', 'Visit the Atelier', 'Contact'],
    },
    {
      header: 'LEGAL',
      links: ['Privacy', 'Terms', 'Warranty'],
    },
  ];

  const columnWidth = 1.2;
  const gutter = 0.375;
  const leftStart = -HALF_W + 2.0 + gutter;
  const columnCenters = columns.map((_, i) => leftStart + i * (columnWidth + gutter) + columnWidth / 2);

  const headerOpts = { fontSize: 9, fontWeight: 700, color: '#16161d', align: 'left' };
  const linkOpts = { fontSize: 13, fontWeight: 400, color: '#16161d', align: 'left' };
  const linkHoverColor = '#ff2a38';
  const timelines = [];

  columns.forEach((col, idx) => {
    const cx = columnCenters[idx];

    // Header
    const headerY = 0.4;
    const header = createText(col.header, headerOpts, { x: cx - columnWidth / 2 + 0.05, y: headerY });
    // Links
    col.links.forEach((link, i) => {
      const linkY = headerY - 0.2 - i * 0.18;
      const txt = createText(link, linkOpts, { x: cx - columnWidth / 2 + 0.05, y: linkY });
      // Hover handling
      const mesh = (txt.isMesh) ? txt : txt.getObjectByProperty('type', 'Mesh');
      if (mesh && mesh.material && mesh.material.color) {
        const original = mesh.material.color.clone();
        const target = new ctx.THREE.Color(linkHoverColor);
        const hoverEnter = () => {
          const tl = gsap.timeline({ defaults: { ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' } });
          tl.to(mesh.material.color, { r: target.r, g: target.g, b: target.b, duration: 0.14 });
          tl.to(mesh.position, { z: 0.02, duration: 0.14 }, 0);
          timelines.push(tl);
        };
        const hoverLeave = () => {
          const tl = gsap.timeline({ defaults: { ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' } });
          tl.to(mesh.material.color, { r: original.r, g: original.g, b: original.b, duration: 0.14 });
          tl.to(mesh.position, { z: 0, duration: 0.14 }, 0);
          timelines.push(tl);
        };
        mesh.userData.handlers = {
          pointerenter: hoverEnter,
          pointerleave: hoverLeave,
        };
      }
    });
  });

  // ----- Legal line -----
  const legalOpts = { fontSize: 9, fontWeight: 400, color: '#16161d', align: 'center' };
  const legalY = -HALF_H + 0.375;
  createText('(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.', legalOpts, {
    x: 0,
    y: legalY,
  });

  // ----- Fade‑up animation -----
  root.position.y = 0.2;
  const fadeTL = gsap.timeline({ defaults: { ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' } });
  fadeTL.to(root.position, { y: 0, duration: 0.5 }, 0);
  fadeMeshes.forEach((m) => {
    fadeTL.to(m.material, { opacity: 1, duration: 0.5 }, 0);
  });
  timelines.push(fadeTL);

  // ----- Cleanup ---
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((mat) => mat.dispose());
          } else {
            obj.material.dispose();
          }
        }
      }
    });
  };

  return root;
}
